local function row(title:string,desc:string,buttons:{any}) local f=Instance.new("Frame");f.Size=UDim2.new(1,-8,0,82);f.BackgroundColor3=Color3.fromRGB(37,51,75);f.Parent=scroll;corner(f);text(f,title,UDim2.new(.52,0,0,25),UDim2.fromOffset(12,8),16);local d=text(f,desc,UDim2.new(.58,0,0,38),UDim2.fromOffset(12,36),12);d.TextWrapped=true;d.TextColor3=Color3.fromRGB(191,202,221);for i,b in ipairs(buttons) do local x=button(f,b[1],UDim2.fromOffset(92,34),UDim2.new(1,-(100*i),.5,-17));x.Activated:Connect(b[2]) end end
local function open(name:string) panel.Visible=true;panelTitle.Text=name;clear()
	if name=="MARKET" then for _,o in ipairs(snapshot.Market or {}) do row(o.Rarity.." • "..o.Name,"$"..o.Price.." | condition "..o.Condition.."% | estimate $"..o.EstimatedLow.."–$"..o.EstimatedHigh,{{"BUY",function()action:FireServer("BuyMarket",o.OfferId)end}}) end
	elseif name=="VEHICLES" then for _,v in ipairs(snapshot.Vehicles or {}) do local avg=0;for _,x in pairs(v.Condition) do avg+=x end;avg=math.floor(avg/5);row(v.Rarity.." • "..v.Name,"Value $"..v.Value.." | condition "..avg.."%",{{"REPAIR",function()action:FireServer("Repair",{Uid=v.Uid,Part="Engine"})end},{"SELL",function()action:FireServer("SellVehicle",v.Uid)end}}) end
	elseif name=="HOME" then local houses=require(ReplicatedStorage.Shared.Config).Houses;for id,h in pairs(houses) do local owned=snapshot.Properties and snapshot.Properties[id];row(h.Name,(owned and "OWNED" or "$"..h.Price).." • Career Lv. "..h.Level,owned and {} or {{"BUY",function()action:FireServer("BuyHouse",id)end}}) end
	elseif name=="QUESTS" then local q=snapshot.Quests and snapshot.Quests.Daily;row("Daily: Complete 3 jobs",q and (q.Jobs.." / 3 • Reward $500 + 5 Gems") or "0 / 3",{{"CLAIM",function()action:FireServer("ClaimQuest")end}});row("Daily Login","Server-timed 7-day reward",{{"CLAIM",function()action:FireServer("Daily")end}})
	elseif name=="PROFILE" then row(player.DisplayName,"Career Lv. "..(snapshot.CareerLevel or 1).." • Net Worth $"..(snapshot.NetWorth or 0),{});row("Lifetime","Jobs "..((snapshot.Statistics and snapshot.Statistics.JobsCompleted) or 0).." • Restored "..((snapshot.Statistics and snapshot.Statistics.CarsRestored) or 0),{})
	else row(name,"Feature catalog and progression are saved to your profile.",{}) end
end
local names={"MARKET","VEHICLES","HOME","QUESTS","PROFILE","SHOP"};for i,n in ipairs(names) do local b=button(nav,n,UDim2.new(1/#names,-8,0,42),UDim2.new((i-1)/#names,4,0,10));b.Activated:Connect(function()open(n)end) end
