(remotes.Sync::RemoteEvent).OnClientEvent:Connect(function(data) snapshot=data;cash.Text="$"..tostring(data.Cash);gems.Text="◆ "..tostring(data.Gems);career.Text="CAREER LV. "..data.CareerLevel;worth.Text="NET WORTH $"..data.NetWorth;for n,l in pairs(needLabels) do l.Text=n.."  "..math.floor(data.Needs[n]) end;local q=data.Quests.Daily;questText.Text=if data.TutorialStep==1 then "CURRENT GOAL\nClean your first trash pile in Town Square!" else "DAILY QUEST\nComplete jobs: "..q.Jobs.." / 3" end)
